        if os.geteuid()==0:raise RuntimeError('nonroot Elasticsearch fixture required')
        self.temp=tempfile.TemporaryDirectory(prefix='of-elasticsearch-');self.root=pathlib.Path(self.temp.name);self.process=None;self.log=None
        try:
            tool=pathlib.Path(os.environ.get('OPSF_ELASTICSEARCH_HOME',str(pathlib.Path(executable).resolve().parents[1]))).resolve()
            config=self.root/'config';shutil.copytree(tool/'config',config)
            for folder in ('data','logs','tmp'):(self.root/folder).mkdir()
            self.port=free_port();transport=free_port()
            while transport==self.port:transport=free_port()
            settings={'cluster.name':'opsforge-private','node.name':'owned-node','path.data':str(self.root/'data'),'path.logs':str(self.root/'logs'),
                'network.host':'127.0.0.1','http.port':self.port,'transport.port':transport,'discovery.type':'single-node',
                'xpack.security.enabled':False,'xpack.ml.enabled':False,'xpack.watcher.enabled':False,
                'node.roles':['master','data','ingest'],'node.store.allow_mmap':False,'ingest.geoip.downloader.enabled':False,
                'cluster.routing.allocation.disk.threshold_enabled':False,'http.max_content_length':'8mb'}
            (config/'elasticsearch.yml').write_text(yaml.safe_dump(settings,sort_keys=False))
            hostname=socket.gethostname();assert not any(c in hostname for c in '\r\n')
            hosts=self.root/'jvm-hosts';hosts.write_text('127.0.0.1 localhost '+hostname+'\n')
            env={**os.environ,'CLI_JAVA_OPTS':'-Djdk.net.hosts.file='+str(hosts),'ES_PATH_CONF':str(config),'ES_TMPDIR':str(self.root/'tmp'),
                'ES_JAVA_OPTS':'-Xms256m -Xmx256m -XX:MaxDirectMemorySize=128m -XX:ActiveProcessorCount=2 -Djdk.net.hosts.file='+str(hosts)}
            # Keystore contains only this disposable node's bootstrap metadata, no external credentials.
            initialized=subprocess.run([str(tool/'bin/elasticsearch-keystore'),'create'],env=env,cwd=self.root,stdin=subprocess.DEVNULL,capture_output=True,text=True,timeout=15)
            if initialized.returncode:raise RuntimeError('private empty keystore initialization failed: '+initialized.stderr[-1500:])
            self.log=(self.root/'startup.log').open('wb')
            self.process=subprocess.Popen([executable],env=env,cwd=self.root,stdin=subprocess.DEVNULL,stdout=self.log,stderr=self.log)
            self.base='http://127.0.0.1:'+str(self.port);deadline=time.monotonic()+65
            while time.monotonic()<deadline:
                if self.process.poll() is not None:raise RuntimeError('private Elasticsearch startup failed: '+(self.root/'startup.log').read_text(errors='replace')[-6000:])
                try:
                    status,document=self.request('GET','/')
                    if status==200:
                        assert document['version']['number']=='8.19.7';break
                except (OSError,urllib.error.URLError):pass
                time.sleep(.15)
            else:raise RuntimeError('private Elasticsearch readiness deadline: '+(self.root/'startup.log').read_text(errors='replace')[-4000:])
            print('NATIVE_ELASTICSEARCH_READY:8.19.7',flush=True);return self
        except BaseException:self.__exit__(None,None,None);raise
    def request(self,method,path,body=None,content_type='application/json'):
        data=body.encode() if isinstance(body,str) else (json.dumps(body).encode() if body is not None else None)
        request=urllib.request.Request(self.base+path,data=data,method=method,headers={'Content-Type':content_type})
        opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
        try:
            with opener.open(request,timeout=5) as response:raw=response.read();return response.status,json.loads(raw) if raw else None
        except urllib.error.HTTPError as response:
            try:return response.code,json.loads(response.read())
            finally:response.close()
    def __exit__(self,*args):
        if self.process is not None:
            if self.process.poll() is None:self.process.terminate()
            try:self.process.wait(timeout=8)
            except subprocess.TimeoutExpired:self.process.kill();self.process.wait(timeout=3)
        if self.log:self.log.close()
        self.temp.cleanup()

